describe('Async Form Submission - Disable Submit Button', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should disable submit button until async form submission is resolved', () => {
    // Intercept the API call
    cy.intercept('POST', '/api/form-submit').as('formSubmit');

    // Verify submit button is enabled initially
    cy.get('[data-testid="submit-button"]').should('be.visible');
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');

    // Fill form fields
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="message-textarea"]').type('Hello, this is a test message');

    // Click submit button
    cy.get('[data-testid="submit-button"]').click();

    // Verify button is disabled during submission
    cy.get('[data-testid="submit-button"]').should('be.disabled');

    // Wait for the API call to complete
    cy.wait('@formSubmit').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify button is re-enabled after successful submission
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');
  });

  it('should re-enable submit button after failed async submission', () => {
    // Intercept the API call with a 500 error
    cy.intercept('POST', '/api/form-submit', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('formSubmitError');

    // Fill form fields
    cy.get('[data-testid="name-input"]').type('Jane Smith');
    cy.get('[data-testid="email-input"]').type('jane@example.com');
    cy.get('[data-testid="message-textarea"]').type('This is a test message');

    // Click submit button
    cy.get('[data-testid="submit-button"]').click();

    // Verify button is disabled during failed submission
    cy.get('[data-testid="submit-button"]').should('be.disabled');

    // Wait for the API call to complete
    cy.wait('@formSubmitError').then((interception) => {
      expect(interception.response.statusCode).to.equal(500);
    });

    // Verify button is re-enabled after error
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Submission failed');
  });
});
